cat > vendor/rustls-platform-verifier/Cargo.toml <<'VEOF'
[package]
name = "rustls-platform-verifier"
version = "0.7.1"
edition = "2021"
description = "Lokalny shim: zamiast weryfikatora platformy (Android/JNI) uzywa wbudowanych certyfikatow webpki-roots. Naprawia panic na Termux/Androidzie."
license = "MIT OR Apache-2.0"

[lib]
name = "rustls_platform_verifier"
path = "src/lib.rs"

[dependencies]
rustls = { version = "0.23", default-features = false, features = ["std", "tls12"] }
webpki-roots = "0.26"
VEOF

cat > vendor/rustls-platform-verifier/src/lib.rs <<'VEOF'
//! Lokalny zamiennik crate'a `rustls-platform-verifier`.
//!
//! Oryginal na Androidzie wymaga inicjalizacji przez JNI (kontekst aplikacji Java)
//! i bez tego PANIKUJE:
//!   "Expect rustls-platform-verifier to be initialized"
//! Co wywalalo bota w momencie skladania pierwszego prawdziwego zlecenia (LIVE).
//!
//! Ten shim implementuje to samo API (`Verifier::new`, `Verifier::new_with_extra_roots`),
//! ale weryfikuje certyfikaty przy uzyciu WBUDOWANYCH korzeni webpki-roots.
//! Nie wymaga Androida, JNI ani systemowego magazynu certyfikatow.

use std::sync::Arc;

use rustls::client::danger::{HandshakeSignatureValid, ServerCertVerified, ServerCertVerifier};
use rustls::client::WebPkiServerVerifier;
use rustls::crypto::CryptoProvider;
use rustls::pki_types::{CertificateDer, ServerName, UnixTime};
use rustls::{DigitallySignedStruct, Error as TlsError, RootCertStore, SignatureScheme};

/// Weryfikator certyfikatow serwera oparty o wbudowane korzenie webpki-roots.
#[derive(Debug)]
pub struct Verifier {
    inner: Arc<WebPkiServerVerifier>,
}

fn roots_with_extra(extra: Vec<CertificateDer<'static>>) -> RootCertStore {
    let mut roots = RootCertStore::empty();
    roots.extend(webpki_roots::TLS_SERVER_ROOTS.iter().cloned());
    for cert in extra {
        let _ = roots.add(cert);
    }
    roots
}

impl Verifier {
    /// Odpowiednik oryginalnego `Verifier::new(provider)`.
    pub fn new(crypto_provider: Arc<CryptoProvider>) -> Result<Self, TlsError> {
        Self::build(roots_with_extra(Vec::new()), crypto_provider)
    }

    /// Odpowiednik oryginalnego `Verifier::new_with_extra_roots(roots, provider)`.
    pub fn new_with_extra_roots(
        extra_roots: Vec<CertificateDer<'static>>,
        crypto_provider: Arc<CryptoProvider>,
    ) -> Result<Self, TlsError> {
        Self::build(roots_with_extra(extra_roots), crypto_provider)
    }

    fn build(roots: RootCertStore, crypto_provider: Arc<CryptoProvider>) -> Result<Self, TlsError> {
        let inner = WebPkiServerVerifier::builder_with_provider(Arc::new(roots), crypto_provider)
            .build()
            .map_err(|e| TlsError::General(format!("webpki verifier build failed: {e}")))?;
        Ok(Self { inner })
    }
}

impl ServerCertVerifier for Verifier {
    fn verify_server_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        intermediates: &[CertificateDer<'_>],
        server_name: &ServerName<'_>,
        ocsp_response: &[u8],
        now: UnixTime,
    ) -> Result<ServerCertVerified, TlsError> {
        self.inner
            .verify_server_cert(end_entity, intermediates, server_name, ocsp_response, now)
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, TlsError> {
        self.inner.verify_tls12_signature(message, cert, dss)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, TlsError> {
        self.inner.verify_tls13_signature(message, cert, dss)
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.inner.supported_verify_schemes()
    }
}
VEOF

say "3/6 Sprawdzam klucz POLYMARKET_PRIVATE_KEY..."
if [ -z "${POLYMARKET_PRIVATE_KEY:-}" ] && [ -f "$HOME/.poly_env" ]; then
  . "$HOME/.poly_env"
fi
if [ -z "${POLYMARKET_PRIVATE_KEY:-}" ]; then
  warn "Nie znalazlem klucza w ~/.poly_env ani w srodowisku."
  printf "Podaj POLYMARKET_PRIVATE_KEY (0x...): "
  read -r POLYMARKET_PRIVATE_KEY < /dev/tty
  if [ -z "$POLYMARKET_PRIVATE_KEY" ]; then
    err "Brak klucza - nie moge dzialac."
    exit 1
  fi
  umask 077
  printf 'export POLYMARKET_PRIVATE_KEY=%s\n' "$POLYMARKET_PRIVATE_KEY" > "$HOME/.poly_env"
  chmod 600 "$HOME/.poly_env"
  say "Zapisalem klucz w ~/.poly_env (prawa 600)."
fi
export POLYMARKET_PRIVATE_KEY

# ---------------------------------------------------------------------------
#  TRYB 'build'  --  pobiera kod i BUDUJE, ale NIE uruchamia bota.
#  Stary (dzialajacy) bot zostaje nietkniety - to osobny proces w pamieci.
#  Po zakonczeniu:  bash finance_6h_start_z_historia_v3.sh run
# ---------------------------------------------------------------------------
if [ "$MODE" = "build" ]; then
  say "4/6 Buduje (LIVE) - stary bot moze dalej dzialac. Cierpliwosci..."
  cargo build --release --features live
  say "GOTOWE. Teraz: Ctrl+C starego bota i uruchom:  bash finance_6h_start_z_historia_v3.sh run"
  exit 0
fi

if [ "$MODE" = "doctor" ]; then
  say "4/6 Buduje (LIVE) - pierwszy build potrwa ~10-15 min..."
  cargo build --release --features live
  say "5/6 Portfel (--doctor)..."
  ./target/release/pm-rust --doctor || true
  say "6/6 Saldo (--balance)..."
  ./target/release/pm-rust --balance || true
  exit 0
fi

if [ "$MODE" = "dry" ]; then
  say "4/6 Buduje (DRY) - pierwszy build potrwa ~10-15 min..."
  cargo build --release
  say "5/6 Uruchamiam PAPER (na sucho). Ctrl+C aby przerwac."
  export SPORTS_MIN_VOLUME="${SPORTS_MIN_VOLUME:-250}"
export SPORTS_MAX_VOLUME="${SPORTS_MAX_VOLUME:-20000}"
  export SPORTS_MAX_MARKETS="${SPORTS_MAX_MARKETS:-2000}"
  export SPORTS_MAX_PAGES="${SPORTS_MAX_PAGES:-5}"
  export SPORTS_DROP="${SPORTS_DROP:-0.40}"
  export SPORTS_REFRESH_SEC="${SPORTS_REFRESH_SEC:-30}"
  exec ./target/release/pm-rust
fi

# ------------------------------- LIVE (domyslnie) ---------------------------
say "4/6 Buduje (LIVE, z SDK + naprawa TLS) - pierwszy build potrwa ~10-15 min. Cierpliwosci..."
cargo build --release --features live

say "5/6 Sprawdzam portfel..."
./target/release/pm-rust --balance || true

say "6/6 URUCHAMIAM LIVE.  Ctrl+C aby przerwac."
warn "To PRAWDZIWE pieniadze. Startuje z malymi stawkami (1\$/pozycja)."
export LIVE=1
export CONFIRM_LIVE=I_UNDERSTAND_THE_RISK
export LIVE_MAX_EXPOSURE="${LIVE_MAX_EXPOSURE:-100000}"
export MAX_SPREAD_CENTS="${MAX_SPREAD_CENTS:-0.03}"
export START_BUDGET="${START_BUDGET:-20.9}"
export MAX_POSITIONS="${MAX_POSITIONS:-20}"
export CAT_MAX_PAGES="${CAT_MAX_PAGES:-25}"
export SPORTS_MIN_VOLUME="${SPORTS_MIN_VOLUME:-250}"
export SPORTS_MAX_VOLUME="${SPORTS_MAX_VOLUME:-20000}"
export SPORTS_MAX_MARKETS="${SPORTS_MAX_MARKETS:-2000}"
export SPORTS_MAX_PAGES="${SPORTS_MAX_PAGES:-5}"
export SPORTS_DROP="${SPORTS_DROP:-0.40}"
export SPORTS_REFRESH_SEC="${SPORTS_REFRESH_SEC:-30}"
printf '\n\033[1;36m[PROGI] FINANCE-2 (6h+historia, A40_40/C30_30)  wolumen>=%s$  spread<=%s  START_BUDGET=%s$  (limit poz: 20 (staly))  SL -90%%  time-exit 2h\033[0m\n' "$SPORTS_MIN_VOLUME" "$MAX_SPREAD_CENTS" "$START_BUDGET"
exec ./target/release/pm-rust
